from __future__ import annotations
import base64, hashlib, io, tarfile
from pathlib import Path
CHUNKS = [
'''''',
'''''',
'''''',
'''''',
'''''',
''''''
]
payload=''.join(CHUNKS)
if len(payload) != 15828 or hashlib.sha256(payload.encode()).hexdigest() != '691b383d40978048011be324b7a8bfc907cc6950d07bfdd882d02d86b6326438':
    raise RuntimeError('Phase 35 payload transport checksum mismatch')
root=Path('.').resolve()
with tarfile.open(fileobj=io.BytesIO(base64.b64decode(payload, validate=True)), mode='r:gz') as tf:
    for member in tf.getmembers():
        target=(root/member.name).resolve()
        if root not in target.parents:
            raise RuntimeError(f'unsafe path: {member.name}')
    tf.extractall(root)
print('Phase 35 files applied')
